    public boolean  validateDelete()
    {
        boolean ok = next validateDelete();
        if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
        {
            GUPPricingAttributeLink  pricingAttributeLink;

            select firstonly RecId from pricingAttributeLink
                    where pricingAttributeLink.AttributeName == this.Name
                    && pricingAttributeLink.TypeName == enum2Str(this.getActualAttributeType().DataType)
                    && pricingAttributeLink.PriceAttributeClassId == classNum(GUPPricingAttributeEcoResAttribute);

            if (pricingAttributeLink.RecId)
            {
                ok = checkFailed("@GlobalUnifiedPricing:GUPErrorDeleteAttrValueOnPricingGroup");
            }
        }

        return ok;
    }
